// Package postgres implements the store against PostgreSQL via pgx/v5 +
// pgxpool: ControlsStore (store.Controls and the resolver),
// RemediationStore (store.Remediations, over the rg_remediator pool) and
// the api role's APIReader. The schema is the controls goose chain under
// migrations_controls/, applied only by `repo-guardian migrate`; queries
// are generated by sqlc into controlsdb/.
//
// The rc line's findings schema (migrations_v2/, sqlcdb/) and the v1
// golang-migrate chain were removed in IMPL-0029 7.5.
//
// All queries are parameterized.
package postgres

import (
	"time"

	"github.com/donaldgifford/repo-guardian/internal/metrics"
)

// observeQuery records the duration of a single store query under
// (operation, outcome). outcome is "ok" if err is nil, "error"
// otherwise.
func observeQuery(operation string, start time.Time, err error) {
	outcome := "ok"
	if err != nil {
		outcome = "error"
	}

	metrics.StoreQuerySeconds.
		WithLabelValues(operation, outcome).
		Observe(time.Since(start).Seconds())
}
